-- Backend Engineering ("The Fracture") Act 7 -- "Permissions" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql).
-- References world-be-7, whose narrative metadata was pre-authored in
-- 20260810045000_backend_acts2_10_and_arc2.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be7', 'world-be-7', 'permissions', '7A - Permissions', 'A second city''s data appeared inside the first city''s dashboard for four seconds. Authentication worked perfectly. Authorization never asked the right question.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be7-1', 'campaign-be7', 'who-can-do-what', 'Who Can Do What', 'Roles, attributes, ownership and tenancy -- the vocabulary and models of deciding what an already-authenticated identity may do.', 1),
  ('operation-be7-2', 'campaign-be7', 'machines-in-the-loop', 'Machines in the Loop', 'API keys, service accounts, secrets, enforcement, and the audit trail that finally explains where a permission check went missing.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be7-01', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'users-roles-permissions', 'Users, Roles, Permissions', 'A second city''s data leaked into the first city''s dashboard for four seconds. Authentication was flawless. Untangling this starts with the vocabulary of who is allowed to do what.', 'intermediate', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"roles-permissions-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 1),
  ('mission-be7-02', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'rbac', 'RBAC', 'Assigning permissions to a role instead of a person scales -- until a role nobody remembers granting is still open on an account nobody''s watching.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be7-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"rbac-matrix-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 2),
  ('mission-be7-03', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'abac-concepts', 'ABAC Concepts', 'Some permissions can''t be captured by a fixed role at all -- they depend on who''s asking, what they''re asking for, and the conditions around the request itself.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be7-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"abac-policy-sim"}'::jsonb, '{"xp":135,"credits":22}'::jsonb, false, 3),
  ('mission-be7-04', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'resource-ownership', 'Resource Ownership', 'A role can say a user is allowed to edit reports. It can''t say which reports are theirs -- and that gap is exactly where this incident started.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be7-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"resource-ownership-sim"}'::jsonb, '{"xp":135,"credits":22}'::jsonb, false, 4),
  ('mission-be7-05', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'multi-tenant-authorization', 'Multi-Tenant Authorization', 'One database, many cities. Ownership isn''t enough when an entire tenant''s worth of rows has to stay invisible to every other tenant, always.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be7-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"multi-tenant-isolation-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 5),
  ('mission-be7-06', 'world-be-7', 'campaign-be7', 'operation-be7-1', 'api-keys', 'API Keys', 'Not every caller is a person sitting behind a login form. Some are scripts, integrations, and dashboards that need their own kind of credential.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be7-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"api-key-lifecycle-sim"}'::jsonb, '{"xp":145,"credits":25}'::jsonb, false, 6),
  ('mission-be7-07', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'service-accounts', 'Service Accounts', 'The request that leaked one city''s data into another''s dashboard didn''t come from a resident at all. It came from a service account nobody was watching closely.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be7-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"service-account-sim"}'::jsonb, '{"xp":160,"credits":28}'::jsonb, false, 7),
  ('mission-be7-08', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'service-to-service-authentication', 'Service-to-Service Authentication', 'When one backend service calls another, there''s no browser, no user and no login form -- just two machines that have to prove themselves to each other anyway.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be7-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"service-to-service-auth-sim"}'::jsonb, '{"xp":165,"credits":28}'::jsonb, false, 8),
  ('mission-be7-09', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'secrets', 'Secrets', 'Every key, password and credential this Act has issued has to live somewhere. Where it lives decides whether it stays a secret at all.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be7-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"secrets-management-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 9),
  ('mission-be7-10', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'authorization-middleware-guards', 'Authorization Middleware/Guards', 'Every route needs the same checks run in the same order, every time. The moment one route is trusted to remember that on its own, one route eventually forgets.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be7-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"authz-middleware-sim"}'::jsonb, '{"xp":175,"credits":30}'::jsonb, false, 10),
  ('mission-be7-11', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'audit-trails', 'Audit Trails', 'Nobody noticed the leak happen. Somebody has to be able to reconstruct it afterward anyway -- who accessed what, and exactly when.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be7-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"audit-trail-sim"}'::jsonb, '{"xp":185,"credits":32}'::jsonb, false, 11),
  ('mission-be7-12', 'world-be-7', 'campaign-be7', 'operation-be7-2', 'the-forbidden-record', 'The Forbidden Record', 'Four seconds, one dashboard, one city''s data where it never should have been. Every lesson this Act taught, aimed at the exact spot the authorization check went missing.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be7-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"forbidden-record-boss-sim"}'::jsonb, '{"xp":420,"credits":90,"badgeIds":["forbidden-record"],"skillXp":{"auth_and_identity":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be7-01', 1, 'mira', 'Four seconds. That''s how long one city''s incident reports sat inside a completely different city''s dashboard before someone noticed and screenshotted it.'),
  ('mission-be7-01', 2, 'mira', 'The login was legitimate. The token was valid. Whoever built that dashboard just never asked the one question that mattered.'),
  ('mission-be7-01', 3, 'forge', 'We''re not chasing a stolen credential this time. We''re chasing a missing question. Start with the vocabulary -- users, roles, permissions -- before we go looking for where it broke.'),
  ('mission-be7-02', 1, 'forge', 'Assigning permissions to a role instead of a person is how you stop repeating yourself at scale. It''s also how a permission outlives the reason it was ever granted.'),
  ('mission-be7-03', 1, 'mira', 'Some access decisions can''t be written as a fixed role at all -- they depend on attributes: whose data it is, what time it is, how sensitive the record is. That''s a different model entirely.'),
  ('mission-be7-04', 1, 'forge', 'A role can say ''editors may edit reports.'' It can''t say which reports belong to which editor. That gap has a name, and it''s exactly where this incident started.'),
  ('mission-be7-05', 1, 'mira', 'One database, many cities, one shared set of tables. Ownership alone doesn''t protect you here -- an entire tenant''s worth of rows has to stay invisible to every other tenant, always, with no exceptions.'),
  ('mission-be7-06', 1, 'forge', 'Not every caller behind an API request is a person who just logged in. Some are scripts, integrations, dashboards -- and they need a credential built for that, not a session.'),
  ('mission-be7-07', 1, 'mira', 'Here''s the part that actually matters: the request that leaked the data didn''t come from a resident at all. It came from a service account. Learn what that even means before we go further.'),
  ('mission-be7-08', 1, 'forge', 'No browser, no login form, no human in the loop -- just one backend service calling another, and somehow still needing to prove who it is.'),
  ('mission-be7-09', 1, 'mira', 'Every key and credential we''ve talked about this Act has to be stored somewhere. Where it lives decides whether it stays a secret or becomes the next incident.'),
  ('mission-be7-10', 1, 'forge', 'Every route is supposed to run the same checks, in the same order, every time. The moment one route is trusted to remember that on its own is the moment one route eventually forgets.'),
  ('mission-be7-11', 1, 'mira', 'Nobody caught this leak while it was happening. Somebody has to be able to reconstruct exactly what happened afterward -- which means it has to be recorded whether anyone''s watching or not.'),
  ('mission-be7-12', 1, 'mira', 'Four seconds. One city''s records, inside another city''s dashboard. I want the actual question that never got asked.'),
  ('mission-be7-12', 2, 'forge', 'I''ve pulled three pieces of evidence from the incident. Each one looks like it could be the root cause. Only one actually is.'),
  ('mission-be7-12', 3, 'mira', 'Judge each on its own merits. Then tell me the authorization pattern that actually prevents this from happening again.'),
  ('mission-be7-12', 4, 'forge', '...one more thing, in the audit trail. The request came through a service account whose route pattern is registered as ''//internal/sync''. Doubled slash. Same mark. It isn''t what caused today''s leak.'),
  ('mission-be7-12', 5, 'mira', 'Noted. Filed, same as every other time we''ve seen it. It''s not today''s fight. But the file on that mark keeps getting thicker.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be7-01-o1', 'mission-be7-01', 1, 'Name the layers', 'Match each concept to what it actually describes.'),
  ('mission-be7-01-o2', 'mission-be7-01', 2, 'Explain the indirection', 'Decide why permissions are usually granted to roles instead of directly to users.'),
  ('mission-be7-02-o1', 'mission-be7-02', 1, 'Build the matrix', 'Match each role to the actions it should be allowed to perform.'),
  ('mission-be7-02-o2', 'mission-be7-02', 2, 'Find the stale grant', 'Find the evidence that explains why a former team member still has elevated access.'),
  ('mission-be7-03-o1', 'mission-be7-03', 1, 'RBAC or ABAC', 'Decide which access model actually fits a rule that depends on more than just a fixed role.'),
  ('mission-be7-03-o2', 'mission-be7-03', 2, 'Sort the attributes', 'Sort each attribute into the category of ABAC input it actually is.'),
  ('mission-be7-04-o1', 'mission-be7-04', 1, 'Find the IDOR', 'Find the evidence that explains how a user edited a report that wasn''t theirs.'),
  ('mission-be7-04-o2', 'mission-be7-04', 2, 'Fix the check', 'Find the line in the handler where the missing ownership check should be.'),
  ('mission-be7-05-o1', 'mission-be7-05', 1, 'Find the leak', 'Find the evidence that explains how one city''s data reached another city''s dashboard.'),
  ('mission-be7-05-o2', 'mission-be7-05', 2, 'Find the missing clause', 'Find the line in the query where tenant scoping should have been enforced.'),
  ('mission-be7-06-o1', 'mission-be7-06', 1, 'Match the property', 'Match each API key property to the problem it actually solves.'),
  ('mission-be7-06-o2', 'mission-be7-06', 2, 'Respond to the leak', 'Decide the correct response after an API key is found committed to a public repository.'),
  ('mission-be7-07-o1', 'mission-be7-07', 1, 'Define the account', 'Decide what actually distinguishes a service account from a user account.'),
  ('mission-be7-07-o2', 'mission-be7-07', 2, 'Find the orphaned credential', 'Find the evidence that explains how a decommissioned integration still had working access.'),
  ('mission-be7-08-o1', 'mission-be7-08', 1, 'Order the handshake', 'Order the steps of a service authenticating to another service using a client-credentials grant.'),
  ('mission-be7-08-o2', 'mission-be7-08', 2, 'Match the pattern', 'Match each service-to-service auth pattern to the property that actually describes it.'),
  ('mission-be7-09-o1', 'mission-be7-09', 1, 'Match the practice', 'Match each secrets-management practice to the problem it solves.'),
  ('mission-be7-09-o2', 'mission-be7-09', 2, 'Find the hardcoded secret', 'Find the line where a credential is hardcoded directly into source.'),
  ('mission-be7-10-o1', 'mission-be7-10', 1, 'Find the unguarded route', 'Find the route that''s missing its authorization check.'),
  ('mission-be7-10-o2', 'mission-be7-10', 2, 'Order the checks', 'Order authentication and authorization the way a request actually has to pass through them.'),
  ('mission-be7-11-o1', 'mission-be7-11', 1, 'Build the entry', 'Match each field a good audit log entry needs to what it actually proves.'),
  ('mission-be7-11-o2', 'mission-be7-11', 2, 'Trace the leak', 'Use the audit trail to find which caller actually accessed the other city''s records.'),
  ('mission-be7-12-o1', 'mission-be7-12', 1, 'Evidence Alpha', 'Judge whether this evidence, on its own, explains the leak.'),
  ('mission-be7-12-o2', 'mission-be7-12', 2, 'Evidence Bravo', 'Judge whether this evidence, on its own, explains the leak.'),
  ('mission-be7-12-o3', 'mission-be7-12', 3, 'Evidence Charlie', 'Judge whether this evidence, on its own, explains the leak.'),
  ('mission-be7-12-o4', 'mission-be7-12', 4, 'Fix the pattern', 'State the authorization pattern that actually prevents this from happening again.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be7-01-o1-c1', 'mission-be7-01-o1', 1, 'drag_and_drop', 'Match each concept to what it actually describes.', '{"items":[{"id":"i1","text":"User"},{"id":"i2","text":"Role"},{"id":"i3","text":"Permission"},{"id":"i4","text":"Grant"}],"targets":[{"id":"t1","label":"A specific identity that can authenticate"},{"id":"t2","label":"A named bundle of permissions, assignable to many users at once"},{"id":"t3","label":"A single, specific allowed action on a specific kind of resource"},{"id":"t4","label":"The act of attaching a role or permission to a specific user"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be7-01-o2-c1', 'mission-be7-01-o2', 1, 'multiple_choice', 'Why do most systems grant permissions to a role, then assign the role to users, instead of granting permissions directly to each user?', '{"question":"Why do most systems grant permissions to a role, then assign the role to users, instead of granting permissions directly to each user?","options":[{"id":"a","text":"Direct grants are technically impossible in most databases"},{"id":"b","text":"Roles are purely cosmetic and change nothing about how checks run"},{"id":"c","text":"A role lets you change what a whole group of users can do in one place, instead of hunting down every user who was individually granted a permission"},{"id":"d","text":"Roles exist only to make audit logs shorter"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be7-02-o1-c1', 'mission-be7-02-o1', 1, 'drag_and_drop', 'Match each role to the action it should be allowed to perform.', '{"items":[{"id":"r1","text":"Viewer"},{"id":"r2","text":"Editor"},{"id":"r3","text":"Admin"}],"targets":[{"id":"t1","label":"Read a report, nothing else"},{"id":"t2","label":"Read and modify a report''s content"},{"id":"t3","label":"Read, modify, delete reports, and manage other users'' roles"}]}'::jsonb, '{"correctMapping":{"r1":"t1","r2":"t2","r3":"t3"}}'::jsonb),
  ('mission-be7-02-o2-c1', 'mission-be7-02-o2', 1, 'investigation', 'Which piece of evidence explains why a former team member still has elevated access?', '{"evidence":[{"id":"ev1","label":"HR record","detail":"the employee''s last day was four months ago"},{"id":"ev2","label":"Role assignment table","detail":"the employee''s account still has the ''regional-admin'' role attached; offboarding only disabled their SSO login, never removed application-level role assignments"},{"id":"ev3","label":"Login history","detail":"the account has had zero successful logins since the employee''s last day"}],"question":"Which piece of evidence explains why a former team member still has elevated access?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be7-03-o1-c1', 'mission-be7-03-o1', 1, 'multiple_choice', 'A policy states: "an inspector may approve a permit only for their own assigned district, and only during business hours." Which model actually fits this rule?', '{"question":"A policy states: \"an inspector may approve a permit only for their own assigned district, and only during business hours.\" Which model actually fits this rule?","options":[{"id":"a","text":"RBAC -- create an ''inspector'' role and stop there"},{"id":"b","text":"ABAC -- the decision depends on attributes of the user (assigned district), the resource (which district it''s in) and the environment (time of day), not just a fixed role name"},{"id":"c","text":"Neither model can express a time-of-day condition"},{"id":"d","text":"RBAC, as long as you create a separate role for every district and every hour of the day"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be7-03-o2-c1', 'mission-be7-03-o2', 1, 'drag_and_drop', 'Sort each attribute into the category of ABAC input it actually is.', '{"items":[{"id":"a1","text":"The requesting user''s department"},{"id":"a2","text":"The sensitivity level marked on the record"},{"id":"a3","text":"The action being attempted (read, edit, delete)"},{"id":"a4","text":"Whether the request is happening during business hours"}],"targets":[{"id":"subject","label":"Subject attribute"},{"id":"resource","label":"Resource attribute"},{"id":"action","label":"Action"},{"id":"environment","label":"Environment attribute"}]}'::jsonb, '{"correctMapping":{"a1":"subject","a2":"resource","a3":"action","a4":"environment"}}'::jsonb),

  ('mission-be7-04-o1-c1', 'mission-be7-04-o1', 1, 'investigation', 'Which piece of evidence explains how a user edited a report that wasn''t theirs?', '{"evidence":[{"id":"ev1","label":"Request log","detail":"PATCH /reports/4471 succeeded for a user who authored report 4409, not 4471"},{"id":"ev2","label":"Handler code","detail":"the update handler fetches the report by the :id in the URL and saves changes without ever comparing report.owner_id to the requesting user''s id"},{"id":"ev3","label":"Role assignment","detail":"the user holds the standard ''editor'' role, which permits editing reports in general"}],"question":"Which piece of evidence explains how a user edited a report that wasn''t theirs?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be7-04-o2-c1', 'mission-be7-04-o2', 1, 'code_debugging', 'Which line is where an ownership check is missing?', '{"language":"javascript","code":"function updateReport(req, res) {\n  const report = db.reports.findById(req.params.id);\n  report.content = req.body.content;\n  db.reports.save(report);\n  res.json(report);\n}","question":"Which line is where an ownership check is missing before the report gets modified?"}'::jsonb, '{"requiredLineIds":["  report.content = req.body.content;"]}'::jsonb),

  ('mission-be7-05-o1-c1', 'mission-be7-05-o1', 1, 'investigation', 'Which piece of evidence explains how one city''s data reached another city''s dashboard?', '{"evidence":[{"id":"ev1","label":"Dashboard query","detail":"SELECT * FROM incident_reports ORDER BY created_at DESC LIMIT 20 -- no tenant_id filter anywhere in the query"},{"id":"ev2","label":"Frontend code","detail":"the dashboard component only renders rows whose tenant_id field matches the logged-in city, once the data arrives in the browser"},{"id":"ev3","label":"Session token","detail":"the token correctly identifies the requesting user as belonging to City A"}],"question":"Which piece of evidence explains how one city''s data reached another city''s dashboard?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be7-05-o2-c1', 'mission-be7-05-o2', 1, 'code_debugging', 'Which line is where tenant scoping should have been enforced?', '{"language":"sql","code":"SELECT id, title, status, created_at\nFROM incident_reports\nORDER BY created_at DESC\nLIMIT 20;","question":"Which line is where a WHERE tenant_id = $1 clause should have been added to enforce tenant scoping?"}'::jsonb, '{"requiredLineIds":["FROM incident_reports"]}'::jsonb),

  ('mission-be7-06-o1-c1', 'mission-be7-06-o1', 1, 'drag_and_drop', 'Match each API key property to the problem it actually solves.', '{"items":[{"id":"p1","text":"Scoped to specific permissions, not full account access"},{"id":"p2","text":"Sent as a header, never in the URL"},{"id":"p3","text":"Hashed at rest in the database"},{"id":"p4","text":"Individually revocable without affecting other keys"}],"targets":[{"id":"t1","label":"Limits the damage a leaked key can do"},{"id":"t2","label":"Keeps the key out of server logs, browser history and referrer headers"},{"id":"t3","label":"Means a database breach doesn''t hand over usable keys"},{"id":"t4","label":"Lets you kill one integration''s access without breaking every other integration"}]}'::jsonb, '{"correctMapping":{"p1":"t1","p2":"t2","p3":"t3","p4":"t4"}}'::jsonb),
  ('mission-be7-06-o2-c1', 'mission-be7-06-o2', 1, 'multiple_choice', 'An API key is found committed in a public GitHub repository. What''s the correct response?', '{"question":"An API key is found committed in a public GitHub repository. What''s the correct response?","options":[{"id":"a","text":"Delete the commit from the repository''s history and consider it resolved"},{"id":"b","text":"Immediately revoke the exposed key and issue a new one, then remove it from history -- treat the key as compromised the moment it was public, regardless of whether misuse has been observed yet"},{"id":"c","text":"Nothing, since the repository is private now"},{"id":"d","text":"Wait to see if the key gets misused before taking any action"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be7-07-o1-c1', 'mission-be7-07-o1', 1, 'multiple_choice', 'What actually distinguishes a service account from a regular user account?', '{"question":"What actually distinguishes a service account from a regular user account?","options":[{"id":"a","text":"A service account is just a user account with a longer password"},{"id":"b","text":"A service account represents a non-human caller -- a script, job, or integration -- and is typically granted narrowly scoped, non-interactive credentials instead of a login form and MFA"},{"id":"c","text":"Service accounts are never allowed to make write requests"},{"id":"d","text":"There is no meaningful difference; the terms are interchangeable"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be7-07-o2-c1', 'mission-be7-07-o2', 1, 'investigation', 'Which piece of evidence explains how a decommissioned integration still had working access?', '{"evidence":[{"id":"ev1","label":"Integration registry","detail":"the ''legacy-weather-sync'' integration was marked decommissioned eight months ago"},{"id":"ev2","label":"Service account record","detail":"the service account issued to that integration was never revoked -- its credentials are still active and still scoped to read/write access on incident_reports"},{"id":"ev3","label":"Vendor contract","detail":"the vendor relationship for that integration formally ended six months ago"}],"question":"Which piece of evidence explains how a decommissioned integration still had working access?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be7-08-o1-c1', 'mission-be7-08-o1', 1, 'interactive_diagram', 'Order the steps of a service authenticating to another service using a client-credentials grant.', '{"diagramId":"client-credentials-flow","hotspots":[{"id":"request_token","label":"Service A requests a token","explanation":"Service A authenticates to the authorization server with its own client ID and secret, no user involved."},{"id":"issue_token","label":"Authorization server issues a scoped token","explanation":"A short-lived token, scoped only to what Service A is allowed to do."},{"id":"call","label":"Service A calls Service B with the token","explanation":"The token is attached to the request as proof of Service A''s identity and permissions."},{"id":"validate","label":"Service B validates the token and its scope","explanation":"Service B checks the token is genuine and covers the specific action being requested before doing anything."}],"task":"Order the steps of a service authenticating to another service using a client-credentials grant."}'::jsonb, '{"correctOrderIds":["request_token","issue_token","call","validate"]}'::jsonb),
  ('mission-be7-08-o2-c1', 'mission-be7-08-o2', 1, 'drag_and_drop', 'Match each service-to-service auth pattern to the property that actually describes it.', '{"items":[{"id":"m1","text":"Shared static API key"},{"id":"m2","text":"mTLS (mutual TLS)"},{"id":"m3","text":"OAuth client-credentials grant"}],"targets":[{"id":"t1","label":"Simple, but hard to rotate without touching every caller at once, and offers no built-in scoping"},{"id":"t2","label":"Both sides present certificates and verify each other at the connection level, before any application data flows"},{"id":"t3","label":"Each service gets its own scoped, short-lived, independently revocable token"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3"}}'::jsonb),

  ('mission-be7-09-o1-c1', 'mission-be7-09-o1', 1, 'drag_and_drop', 'Match each secrets-management practice to the problem it solves.', '{"items":[{"id":"s1","text":"Storing secrets in a dedicated secrets manager/vault, not in source control"},{"id":"s2","text":"Reading secrets from environment variables injected at runtime"},{"id":"s3","text":"Rotating secrets on a schedule"},{"id":"s4","text":"Granting each service access to only the secrets it actually needs"}],"targets":[{"id":"t1","label":"A leaked repository doesn''t automatically leak production credentials"},{"id":"t2","label":"The same code can run against different environments without the secret being baked into the code itself"},{"id":"t3","label":"Limits how long a secret stays useful even if it does leak undetected"},{"id":"t4","label":"One compromised service can''t be used to reach every other service''s secrets"}]}'::jsonb, '{"correctMapping":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb),
  ('mission-be7-09-o2-c1', 'mission-be7-09-o2', 1, 'code_debugging', 'Which line is the hardcoded secret?', '{"language":"javascript","code":"const dbHost = process.env.DB_HOST;\nconst dbUser = process.env.DB_USER;\nconst dbPassword = \"fr0ntier-city-2024\";\nconst client = new DbClient({ host: dbHost, user: dbUser, password: dbPassword });","question":"Three of these lines read configuration from the environment. Which line is the hardcoded secret?"}'::jsonb, '{"requiredLineIds":["const dbPassword = \"fr0ntier-city-2024\";"]}'::jsonb),

  ('mission-be7-10-o1-c1', 'mission-be7-10-o1', 1, 'code_debugging', 'Four routes are registered below. Which one is missing its authorization guard?', '{"language":"javascript","code":"router.get(\"/reports\", requireAuth, requireRole(\"viewer\"), listReports);\nrouter.post(\"/reports\", requireAuth, requireRole(\"editor\"), createReport);\nrouter.delete(\"/reports/:id\", requireAuth, requireRole(\"admin\"), deleteReport);\nrouter.patch(\"/reports/:id\", requireAuth, updateReport);","question":"Four routes are registered below. Which one is missing its authorization guard?"}'::jsonb, '{"requiredLineIds":["router.patch(\"/reports/:id\", requireAuth, updateReport);"]}'::jsonb),
  ('mission-be7-10-o2-c1', 'mission-be7-10-o2', 1, 'interactive_diagram', 'Order the checks the way a request actually has to pass through them.', '{"diagramId":"authz-middleware-order","hotspots":[{"id":"authenticate","label":"Authenticate the request","explanation":"Confirm the token/session is valid and establish who is making the request."},{"id":"authorize_role","label":"Check role/permission","explanation":"Confirm the now-known identity is allowed to perform this kind of action at all."},{"id":"authorize_resource","label":"Check resource-level access","explanation":"Confirm the identity is allowed to act on this specific resource -- ownership or tenant scoping."},{"id":"handle","label":"Run the handler","explanation":"Only once every prior check has passed does the actual business logic run."}],"task":"Order the checks the way a request actually has to pass through them."}'::jsonb, '{"correctOrderIds":["authenticate","authorize_role","authorize_resource","handle"]}'::jsonb),

  ('mission-be7-11-o1-c1', 'mission-be7-11-o1', 1, 'drag_and_drop', 'Match each field a good audit log entry needs to what it actually proves.', '{"items":[{"id":"f1","text":"Actor identity (which user or service account)"},{"id":"f2","text":"Action performed"},{"id":"f3","text":"Resource affected, specifically"},{"id":"f4","text":"Timestamp"},{"id":"f5","text":"Immutability -- the entry can''t be edited or deleted afterward"}],"targets":[{"id":"t1","label":"Who did it"},{"id":"t2","label":"What they did"},{"id":"t3","label":"What it was done to"},{"id":"t4","label":"When it happened"},{"id":"t5","label":"That the record itself can be trusted later"}]}'::jsonb, '{"correctMapping":{"f1":"t1","f2":"t2","f3":"t3","f4":"t4","f5":"t5"}}'::jsonb),
  ('mission-be7-11-o2-c1', 'mission-be7-11-o2', 1, 'investigation', 'Which audit trail entry identifies the actual caller behind the leak?', '{"evidence":[{"id":"ev1","label":"Audit entry 1","detail":"actor: resident-4471, action: VIEW, resource: incident_reports (own city), result: allowed"},{"id":"ev2","label":"Audit entry 2","detail":"actor: svc-dashboard-sync, action: LIST, resource: incident_reports (all tenants, no tenant_id filter recorded), result: allowed"},{"id":"ev3","label":"Audit entry 3","detail":"actor: resident-8802, action: LOGIN, resource: auth-service, result: allowed"}],"question":"Which audit trail entry identifies the actual caller behind the leak?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be7-12-o1-c1', 'mission-be7-12-o1', 1, 'multiple_choice', 'Evidence Alpha: the session token involved was valid and correctly identified the requesting service account. Does this explain the leak?', '{"question":"Evidence Alpha: the session token involved was valid and correctly identified the requesting service account. Does this explain the leak?","options":[{"id":"a","text":"Yes -- a valid token is exactly what let the data through"},{"id":"b","text":"No -- authentication succeeding just confirms who was asking; it says nothing about whether that identity should have seen rows belonging to another tenant"},{"id":"c","text":"Yes -- service accounts should never hold valid tokens"},{"id":"d","text":"Unknowable without seeing the token''s signature"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be7-12-o2-c1', 'mission-be7-12-o2', 1, 'multiple_choice', 'Evidence Bravo: the dashboard''s backend query selected from incident_reports with no WHERE clause scoping it to a tenant, relying on the frontend to filter what it displayed. Does this explain the leak?', '{"question":"Evidence Bravo: the dashboard''s backend query selected from incident_reports with no WHERE clause scoping it to a tenant, relying on the frontend to filter what it displayed. Does this explain the leak?","options":[{"id":"a","text":"No -- frontend filtering is always sufficient on its own"},{"id":"b","text":"Yes -- the data left the server ungated; any response inspection, timing gap, or frontend bug exposes rows that should never have been fetched in the first place"},{"id":"c","text":"No -- this only matters if the frontend code has a bug"},{"id":"d","text":"Unknowable without seeing the frontend framework"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be7-12-o3-c1', 'mission-be7-12-o3', 1, 'multiple_choice', 'Evidence Charlie: the two cities'' internal record IDs happen to sit in adjacent numeric ranges. Does this fact, by itself, explain the leak?', '{"question":"Evidence Charlie: the two cities'' internal record IDs happen to sit in adjacent numeric ranges. Does this fact, by itself, explain the leak?","options":[{"id":"a","text":"Yes -- adjacent ID ranges are inherently a vulnerability"},{"id":"b","text":"No -- it explains which specific rows were visible in this instance, not why the query was able to reach across tenants at all; it''s a coincidence of the data, not the mechanism"},{"id":"c","text":"Yes -- IDs should always be randomly distributed to prevent this"},{"id":"d","text":"Unknowable without seeing the ID generation strategy"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be7-12-o4-c1', 'mission-be7-12-o4', 1, 'boss_encounter', 'Having judged all three pieces of evidence, state the authorization pattern that actually prevents this from happening again.', '{"stages":[{"objectiveRef":"mission-be7-12-o1","label":"Evidence Alpha"},{"objectiveRef":"mission-be7-12-o2","label":"Evidence Bravo"},{"objectiveRef":"mission-be7-12-o3","label":"Evidence Charlie"}],"task":"Having judged all three pieces of evidence, state the authorization pattern that actually prevents this from happening again: tenant and ownership scoping must be enforced at the data-access layer itself -- every query scoped by tenant_id at the source -- never left to the frontend or any other trusted client to filter correctly after the fact."}'::jsonb, '{"requiredObjectiveIds":["mission-be7-12-o1","mission-be7-12-o2","mission-be7-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be7-01-o1-c1', 'orientation', 'One of these is a person or a machine. The others describe how permission actually moves.', 10, 1),
  ('mission-be7-01-o1-c1', 'solution', 'i1 -> an identity that authenticates, i2 -> a named bundle of permissions, i3 -> one specific allowed action, i4 -> the act of attaching a role/permission to a user.', 20, 2),
  ('mission-be7-01-o2-c1', 'orientation', 'Think about what has to change when fifty users all need the same new permission at once.', 10, 1),
  ('mission-be7-01-o2-c1', 'solution', 'c -- a role is a single place to change what a whole group can do, instead of editing every user individually.', 20, 2),

  ('mission-be7-02-o1-c1', 'orientation', 'Each role should be a strict superset of the one below it here.', 10, 1),
  ('mission-be7-02-o1-c1', 'solution', 'Viewer -> read only. Editor -> read and modify. Admin -> read, modify, delete, and manage other users'' roles.', 20, 2),
  ('mission-be7-02-o2-c1', 'orientation', 'Disabling a login and removing a permission are two different actions -- check whether both actually happened.', 10, 1),
  ('mission-be7-02-o2-c1', 'concept', 'Offboarding often stops at identity (can they log in?) without touching authorization (what can the account still do if it somehow can?).', 20, 2),
  ('mission-be7-02-o2-c1', 'solution', 'ev2 -- the role assignment itself was never removed; only the login was disabled, and the two aren''t the same control.', 30, 3),

  ('mission-be7-03-o1-c1', 'orientation', 'Count how many independent variables this rule actually depends on.', 10, 1),
  ('mission-be7-03-o1-c1', 'concept', 'A rule that depends on district, resource location, and time of day can''t be captured by a role name alone without exploding into hundreds of roles.', 20, 2),
  ('mission-be7-03-o1-c1', 'solution', 'b -- this is a textbook ABAC rule: it evaluates subject, resource and environment attributes together at request time.', 30, 3),
  ('mission-be7-03-o2-c1', 'orientation', 'Ask, for each item: is this about the requester, the thing being accessed, what''s being done, or the surrounding context?', 10, 1),
  ('mission-be7-03-o2-c1', 'solution', 'Department -> subject. Sensitivity level -> resource. The action itself -> action. Business hours -> environment.', 20, 2),

  ('mission-be7-04-o1-c1', 'orientation', 'A valid role and a legitimate action type don''t answer the question ''whose record is this.''', 10, 1),
  ('mission-be7-04-o1-c1', 'concept', 'This is a classic insecure direct object reference: the request is well-formed and the user has a legitimate role, but nobody checked which specific resource the role applies to.', 20, 2),
  ('mission-be7-04-o1-c1', 'solution', 'ev2 -- the handler never compares the report''s owner to the requesting user, so any authenticated editor can modify any report by ID.', 30, 3),
  ('mission-be7-04-o2-c1', 'orientation', 'The bug isn''t in how the report is fetched. It''s in what happens right after.', 10, 1),
  ('mission-be7-04-o2-c1', 'solution', 'The mutation itself -- report.content = req.body.content; -- runs with no check that report.owner_id matches the requesting user first.', 20, 2),

  ('mission-be7-05-o1-c1', 'orientation', 'A filter that only exists in the browser only protects users who never look at network traffic directly.', 10, 1),
  ('mission-be7-05-o1-c1', 'concept', 'Anything scoped only on the frontend has already left the server for every tenant, not just the one being displayed.', 20, 2),
  ('mission-be7-05-o1-c1', 'solution', 'ev1 -- the backend query itself has no tenant_id filter; it returns every tenant''s rows and trusts the frontend to hide the rest.', 30, 3),
  ('mission-be7-05-o2-c1', 'orientation', 'The fix belongs in the same clause that already limits which rows come back.', 10, 1),
  ('mission-be7-05-o2-c1', 'solution', 'FROM incident_reports -- this is where a WHERE tenant_id = $1 clause needs to scope the query at its source.', 20, 2),

  ('mission-be7-06-o1-c1', 'orientation', 'Each property maps to one specific way a leaked key could otherwise be misused.', 10, 1),
  ('mission-be7-06-o1-c1', 'solution', 'Scoped -> limits blast radius. Header, not URL -> avoids accidental logging/leakage. Hashed at rest -> a DB breach doesn''t hand over the key. Individually revocable -> kill one integration without breaking the rest.', 20, 2),
  ('mission-be7-06-o2-c1', 'orientation', 'Treat exposure itself as the incident, not proof that someone actually used it maliciously.', 10, 1),
  ('mission-be7-06-o2-c1', 'solution', 'b -- revoke and reissue immediately; a key is compromised the moment it becomes public, whether or not misuse has been observed yet.', 20, 2),

  ('mission-be7-07-o1-c1', 'orientation', 'Ask who -- or what -- is actually behind the credential.', 10, 1),
  ('mission-be7-07-o1-c1', 'solution', 'b -- a service account represents a non-human caller and typically gets narrow, non-interactive credentials instead of a login-and-MFA flow.', 20, 2),
  ('mission-be7-07-o2-c1', 'orientation', 'Ending a vendor contract and revoking a credential are two separate steps -- check whether the second one actually happened.', 10, 1),
  ('mission-be7-07-o2-c1', 'solution', 'ev2 -- the service account''s credentials were never revoked when the integration was decommissioned, so they still work.', 30, 3),

  ('mission-be7-08-o1-c1', 'orientation', 'A token can''t be validated by the receiver until it''s actually been sent, and it can''t be issued until someone proves who''s asking.', 10, 1),
  ('mission-be7-08-o1-c1', 'solution', 'Service A requests a token with its own credentials, the authorization server issues a scoped token, Service A calls Service B with it, Service B validates the token and its scope.', 20, 2),
  ('mission-be7-08-o2-c1', 'orientation', 'One of these operates below the application layer entirely; one is the simplest and hardest to rotate; one borrows the OAuth model you already learned.', 10, 1),
  ('mission-be7-08-o2-c1', 'solution', 'Shared static key -> simple but hard to rotate, no scoping. mTLS -> mutual certificate verification at the connection level. OAuth client-credentials -> scoped, short-lived, independently revocable tokens.', 20, 2),

  ('mission-be7-09-o1-c1', 'orientation', 'Each practice closes off one specific way a secret could otherwise spread further than it should.', 10, 1),
  ('mission-be7-09-o1-c1', 'solution', 'Vault, not source control -> a leaked repo isn''t a leaked credential. Env vars -> same code, different environments. Rotation -> limits the useful life of a leak. Least privilege -> one breach doesn''t cascade to every secret.', 20, 2),
  ('mission-be7-09-o2-c1', 'orientation', 'Three of these four lines pull from process.env. One doesn''t.', 10, 1),
  ('mission-be7-09-o2-c1', 'solution', 'const dbPassword = "fr0ntier-city-2024"; -- a literal credential baked directly into the source file instead of read from the environment.', 20, 2),

  ('mission-be7-10-o1-c1', 'orientation', 'Every other route pairs requireAuth with a requireRole check. Look for the one that doesn''t.', 10, 1),
  ('mission-be7-10-o1-c1', 'solution', 'router.patch("/reports/:id", requireAuth, updateReport); -- authenticated, but with no requireRole (or ownership) guard at all before updateReport runs.', 20, 2),
  ('mission-be7-10-o2-c1', 'orientation', 'You can''t decide what someone''s allowed to do before you know who they are, and you can''t decide whether this specific resource is theirs before you know what actions their role even permits.', 10, 1),
  ('mission-be7-10-o2-c1', 'solution', 'Authenticate, then check role/permission, then check resource-level access (ownership/tenant), then run the handler.', 20, 2),

  ('mission-be7-11-o1-c1', 'orientation', 'A good audit entry answers who, what, to what, when -- and whether you can trust it later.', 10, 1),
  ('mission-be7-11-o1-c1', 'solution', 'Actor -> who did it. Action -> what they did. Resource -> what it was done to. Timestamp -> when. Immutability -> that the record can still be trusted afterward.', 20, 2),
  ('mission-be7-11-o2-c1', 'orientation', 'Look for the entry whose resource scope doesn''t match what a single-tenant request should ever touch.', 10, 1),
  ('mission-be7-11-o2-c1', 'solution', 'ev2 -- svc-dashboard-sync listed incident_reports across all tenants with no tenant_id filter recorded, and the request was still allowed.', 30, 3),

  ('mission-be7-12-o1-c1', 'orientation', 'Authentication and authorization are two different questions -- this evidence only speaks to one of them.', 10, 1),
  ('mission-be7-12-o1-c1', 'solution', 'b -- the token being valid just confirms identity; it says nothing about whether that identity should see another tenant''s rows.', 20, 2),
  ('mission-be7-12-o2-c1', 'orientation', 'Ask where the untrusted boundary actually sits between the database and the browser.', 10, 1),
  ('mission-be7-12-o2-c1', 'solution', 'b -- once ungated data leaves the server, the frontend is the only thing standing between it and exposure, and that''s not a security boundary.', 20, 2),
  ('mission-be7-12-o3-c1', 'orientation', 'This fact explains which rows were visible, not why the query could reach them at all.', 10, 1),
  ('mission-be7-12-o3-c1', 'solution', 'b -- adjacent ID ranges are incidental; the mechanism that let the query cross tenants in the first place is the actual defect.', 20, 2),
  ('mission-be7-12-o4-c1', 'orientation', 'Look at what all three judgments pointed away from, and the one layer none of them could substitute for.', 15, 1),
  ('mission-be7-12-o4-c1', 'solution', 'Tenant and ownership scoping has to be enforced at the data-access layer itself -- every query scoped by tenant_id at the source, checked on the server, never delegated to the frontend or any other client to filter correctly after the fact.', 25, 2);
